def classify(profile):
    if profile['data_factor'] >= 2:
        return 'volume'
    if profile['peak_factor'] >= 2 and profile['ramp_seconds'] <= 60:
        return 'spike'
    if profile['peak_factor'] > 1:
        return 'stress'
    if profile['duration_hours'] >= 4:
        return 'soak'
    return 'load'
